def compute(vars):
    operating_earnings = vars["v1"]
    segment_net_sales = vars["v2"]

    if segment_net_sales == 0:
        return None

    ratio = operating_earnings / segment_net_sales
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "operating_earnings": operating_earnings,
            "segment_net_sales": segment_net_sales,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
